# Windows Update Repair Script
# Generated by ANA MAX OS-27
# This script repairs Windows Update components

Write-Host "====================================" -ForegroundColor Cyan
Write-Host "WINDOWS UPDATE REPAIR SCRIPT" -ForegroundColor Cyan
Write-Host "====================================" -ForegroundColor Cyan
Write-Host ""

# Check if running as Administrator
$isAdmin = ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Host "ERROR: This script must be run as Administrator!" -ForegroundColor Red
    Write-Host "Right-click PowerShell and select 'Run as Administrator'" -ForegroundColor Yellow
    exit 1
}

Write-Host "Step 1: Stopping Windows Update services..." -ForegroundColor Yellow
Stop-Service -Name wuauserv -Force -ErrorAction SilentlyContinue
Stop-Service -Name bits -Force -ErrorAction SilentlyContinue
Stop-Service -Name cryptsvc -Force -ErrorAction SilentlyContinue
Write-Host "Services stopped." -ForegroundColor Green

Write-Host ""
Write-Host "Step 2: Renaming Windows Update cache folders..." -ForegroundColor Yellow
$paths = @(
    "$env:SYSTEMROOT\SoftwareDistribution",
    "$env:SYSTEMROOT\SoftwareDistribution.old",
    "$env:SYSTEMROOT\SoftwareDistribution.bak",
    "$env:SYSTEMROOT\System32\catroot2"
)

foreach ($path in $paths) {
    if (Test-Path $path) {
        $newPath = $path + ".old"
        if (Test-Path $newPath) {
            Remove-Item $newPath -Recurse -Force -ErrorAction SilentlyContinue
        }
        Rename-Item -Path $path -NewName $newPath -ErrorAction SilentlyContinue
        Write-Host "Renamed: $path -> $newPath" -ForegroundColor Green
    }
}

Write-Host ""
Write-Host "Step 3: Re-registering COM components..." -ForegroundColor Yellow
$comDlls = @(
    "atl.dll",
    "urlmon.dll",
    "mshtml.dll",
    "shdocvw.dll",
    "browseui.dll",
    "jscript.dll",
    "vbscript.dll",
    "scrrun.dll",
    "msxml.dll",
    "msxml2.dll",
    "msxml3.dll",
    "softpub.dll",
    "wintrust.dll",
    "initpki.dll",
    "dssenh.dll",
    "rsaenh.dll",
    "gpkcsp.dll",
    "sccbase.dll",
    "slbcsp.dll",
    "cryptdlg.dll",
    "oleaut32.dll",
    "ole32.dll",
    "shell32.dll",
    "initpki.dll",
    "wuapi.dll",
    "wuaueng.dll",
    "wuaueng1.dll",
    "wucltui.dll",
    "wups.dll",
    "wups2.dll",
    "wuweb.dll",
    "qmgr.dll",
    "qmgrprxy.dll",
    "wucltux.dll",
    "muweb.dll",
    "wuwebv.dll"
)

foreach ($dll in $comDlls) {
    $dllPath = Join-Path $env:SYSTEMROOT "System32\$dll"
    if (Test-Path $dllPath) {
        Write-Host "Registering: $dll" -ForegroundColor DarkGray
        regsvr32 /s $dllPath
    }
}

Write-Host "COM components re-registered." -ForegroundColor Green

Write-Host ""
Write-Host "Step 4: Repairing Windows image with DISM..." -ForegroundColor Yellow
Write-Host "This may take several minutes..." -ForegroundColor Yellow
dism /online /cleanup-image /restorehealth
Write-Host "DISM scan completed." -ForegroundColor Green

Write-Host ""
Write-Host "Step 5: Running System File Checker (SFC)..." -ForegroundColor Yellow
Write-Host "This may take several minutes..." -ForegroundColor Yellow
sfc /scannow
Write-Host "SFC scan completed." -ForegroundColor Green

Write-Host ""
Write-Host "Step 6: Restarting Windows Update services..." -ForegroundColor Yellow
Start-Service -Name cryptsvc -ErrorAction SilentlyContinue
Start-Service -Name bits -ErrorAction SilentlyContinue
Start-Service -Name wuauserv -ErrorAction SilentlyContinue
Write-Host "Services restarted." -ForegroundColor Green

Write-Host ""
Write-Host "Step 7: Verifying service status..." -ForegroundColor Yellow
Get-Service wuauserv, bits, cryptsvc | Select-Object Name, Status, StartType

Write-Host ""
Write-Host "====================================" -ForegroundColor Cyan
Write-Host "REPAIR COMPLETED" -ForegroundColor Green
Write-Host "====================================" -ForegroundColor Cyan
Write-Host ""
Write-Host "Next steps:" -ForegroundColor Yellow
Write-Host "1. Restart your computer" -ForegroundColor White
Write-Host "2. Run Windows Update again" -ForegroundColor White
Write-Host "3. If the error persists, check Event Viewer for more details" -ForegroundColor White
Write-Host ""
